constexpr double PI_VAL   = 3.14159265358979323846;
constexpr double E_VAL    = 2.71828182845904523536;
constexpr double PHI_VAL  = 1.61803398874989484820;
constexpr double C_VAL    = 299792458.0;              // Speed of light m/s
constexpr double H_VAL    = 6.62607015e-34;           // Planck constant J*s
constexpr double G_VAL    = 6.67430e-11;              // Gravitational constant
constexpr double NA_VAL   = 6.02214076e23;            // Avogadro constant
constexpr double K_VAL    = 1.380649e-23;             // Boltzmann constant

double factorial(double n) {
    if (n < 0 || std::floor(n) != n) {
        throw std::domain_error("Factorial requires non-negative integer");
    }
    if (n > 170.0) {
        throw std::overflow_error("Factorial overflow (>170!)");
    }
    double result = 1.0;
    for (int i = 2; i <= static_cast<int>(n); ++i) {
        result *= i;
    }
    return result;
}

double combinations(double n, double r) {
    if (n < 0 || r < 0 || r > n || std::floor(n) != n || std::floor(r) != r) {
        throw std::domain_error("nCr requires non-negative integers with n >= r");
    }
    r = std::min(r, n - r);
    double res = 1.0;
    for (int i = 1; i <= static_cast<int>(r); ++i) {
        res = res * (n - r + i) / i;
    }
    return res;
}

double permutations(double n, double r) {
    if (n < 0 || r < 0 || r > n || std::floor(n) != n || std::floor(r) != r) {
        throw std::domain_error("nPr requires non-negative integers with n >= r");
    }
    double res = 1.0;
    for (int i = 0; i < static_cast<int>(r); ++i) {
        res *= (n - i);
    }
    return res;
}

enum class TokenType {
    Number,
    Identifier,
    Plus,
    Minus,
    Multiply,
    Divide,
    Modulo,
    Power,
    Factorial,
    Percent,
    OpenParen,
    CloseParen,
    Comma,
    End
};

struct Token {
    TokenType type;
    double numberValue = 0.0;
    std::string stringValue;
};

class Lexer {
public:
    explicit Lexer(std::string_view input) : m_input(input), m_pos(0) {}

    Token nextToken() {
        skipWhitespace();
        if (m_pos >= m_input.length()) {
            return Token{TokenType::End, 0.0, ""};
        }

        char c = m_input[m_pos];

        // Number
        if (std::isdigit(c) || c == '.') {
            size_t start = m_pos;
            bool seenDot = (c == '.');
            m_pos++;
            while (m_pos < m_input.length()) {
                char ch = m_input[m_pos];
                if (ch == '.') {
                    if (seenDot) break;
                    seenDot = true;
                    m_pos++;
                } else if (std::isdigit(ch)) {
                    m_pos++;
                } else if (ch == 'e' || ch == 'E') {
                    if (m_pos + 1 < m_input.length() && (m_input[m_pos + 1] == '+' || m_input[m_pos + 1] == '-' || std::isdigit(m_input[m_pos + 1]))) {
                        m_pos += 2;
                        while (m_pos < m_input.length() && std::isdigit(m_input[m_pos])) {
                            m_pos++;
                        }
                    }
                    break;
                } else {
                    break;
                }
            }
            std::string numStr = std::string(m_input.substr(start, m_pos - start));
            try {
                double val = std::stod(numStr);
                return Token{TokenType::Number, val, numStr};
            } catch (...) {
                throw std::runtime_error("Invalid number: " + numStr);
            }
        }

        // Identifier (function name or constant)
        if (std::isalpha(c) || c == '_') {
            size_t start = m_pos;
            while (m_pos < m_input.length() && (std::isalnum(m_input[m_pos]) || m_input[m_pos] == '_')) {
                m_pos++;
            }
            std::string id = std::string(m_input.substr(start, m_pos - start));
            return Token{TokenType::Identifier, 0.0, id};
        }

        m_pos++;
        switch (c) {
            case '+': return Token{TokenType::Plus, 0.0, "+"};
            case '-': return Token{TokenType::Minus, 0.0, "-"};
            case '*': return Token{TokenType::Multiply, 0.0, "*"};
            case '/': return Token{TokenType::Divide, 0.0, "/"};
            case '%': return Token{TokenType::Modulo, 0.0, "%"};
            case '^': return Token{TokenType::Power, 0.0, "^"};
            case '!': return Token{TokenType::Factorial, 0.0, "!"};
            case '(': return Token{TokenType::OpenParen, 0.0, "("};
            case ')': return Token{TokenType::CloseParen, 0.0, ")"};
            case ',': return Token{TokenType::Comma, 0.0, ","};
            default:
                throw std::runtime_error(std::string("Unexpected character: ") + c);
        }
    }

private:
    std::string_view m_input;
    size_t m_pos;

    void skipWhitespace() {
        while (m_pos < m_input.length() && std::isspace(m_input[m_pos])) {
            m_pos++;
        }
    }
};

class RecursiveDescentParser {
public:
    RecursiveDescentParser(std::string_view input, const MathParser* parent)
        : m_lexer(input), m_parent(parent) {
        advance();
    }

    double parse() {
        double val = parseExpression();
        if (m_current.type != TokenType::End) {
            throw std::runtime_error("Unexpected token after expression: " + m_current.stringValue);
        }
        return val;
    }

private:
    Lexer m_lexer;
    const MathParser* m_parent;
    Token m_current;

    void advance() {
        m_current = m_lexer.nextToken();
    }

    int getPrecedence(TokenType type) {
        switch (type) {
            case TokenType::Plus:
            case TokenType::Minus:
                return 1;
            case TokenType::Multiply:
            case TokenType::Divide:
            case TokenType::Modulo:
                return 2;
            case TokenType::Power:
                return 3;
            default:
                return 0;
        }
    }

    double parseExpression() {
        return parseBinary(1);
    }

    double parseBinary(int minPrec) {
        double left = parseUnary();

        while (true) {
            // Check for implicit multiplication: if current token is OpenParen, Number, or Identifier
            if (m_current.type == TokenType::OpenParen ||
                m_current.type == TokenType::Number ||
                m_current.type == TokenType::Identifier) {
                int prec = getPrecedence(TokenType::Multiply);
                if (prec >= minPrec) {
                    double right = parseBinary(prec + 1);
                    left = left * right;
                    continue;
                }
            }

            int prec = getPrecedence(m_current.type);
            if (prec < minPrec) {
                break;
            }

            TokenType op = m_current.type;
            advance();

            int nextPrec = (op == TokenType::Power) ? prec : (prec + 1);
            double right = parseBinary(nextPrec);

            switch (op) {
                case TokenType::Plus:
                    left += right;
                    break;
                case TokenType::Minus:
                    left -= right;
                    break;
                case TokenType::Multiply:
                    left *= right;
                    break;
                case TokenType::Divide:
                    if (right == 0.0) throw std::domain_error("Division by zero");
                    left /= right;
                    break;
                case TokenType::Modulo:
                    if (right == 0.0) throw std::domain_error("Modulo by zero");
                    left = std::fmod(left, right);
                    break;
                case TokenType::Power:
                    left = std::pow(left, right);
                    break;
                default:
                    break;
            }
        }

        return left;
    }

    double parseUnary() {
        if (m_current.type == TokenType::Plus) {
            advance();
            return parseUnary();
        }
        if (m_current.type == TokenType::Minus) {
            advance();
            return -parseUnary();
        }

        double val = parsePrimary();

        // Handle postfix operators: ! and %
        while (m_current.type == TokenType::Factorial || m_current.type == TokenType::Modulo) {
            if (m_current.type == TokenType::Factorial) {
                advance();
                val = factorial(val);
            } else if (m_current.type == TokenType::Modulo) {
                // If % follows a primary and is immediately followed by an operator, close paren, or end, treat as percentage
                advance();
                val = val / 100.0;
            }
        }

        return val;
    }

    double parsePrimary() {
        if (m_current.type == TokenType::Number) {
            double val = m_current.numberValue;
            advance();
            return val;
        }

        if (m_current.type == TokenType::OpenParen) {
            advance();
            double val = parseExpression();
            if (m_current.type == TokenType::CloseParen) {
                advance();
            }
            return val;
        }

        if (m_current.type == TokenType::Identifier) {
            std::string id = m_current.stringValue;
            std::transform(id.begin(), id.end(), id.begin(), ::tolower);
            advance();

            // Check if it is a constant
            if (id == "pi") return PI_VAL;
            if (id == "e") return E_VAL;
            if (id == "phi") return PHI_VAL;
            if (id == "c") return C_VAL;
            if (id == "h") return H_VAL;
            if (id == "g") return G_VAL;
            if (id == "na") return NA_VAL;
            if (id == "k") return K_VAL;

            // Otherwise, it must be a function call with arguments: func(arg) or func(arg1, arg2)
            if (m_current.type == TokenType::OpenParen) {
                advance();
                std::vector<double> args;
                if (m_current.type != TokenType::CloseParen) {
                    args.push_back(parseExpression());
                    while (m_current.type == TokenType::Comma) {
                        advance();
                        args.push_back(parseExpression());
                    }
                }
                if (m_current.type == TokenType::CloseParen) {
                    advance();
                }

                return executeFunction(id, args);
            }

            throw std::runtime_error("Unknown identifier: " + id);
        }

        throw std::runtime_error("Syntax error at: " + m_current.stringValue);
    }

    double executeFunction(const std::string& name, const std::vector<double>& args) {
        if (args.empty()) {
            throw std::runtime_error("Function " + name + " requires arguments");
        }

        double x = args[0];

        // 1-argument functions
        if (name == "sqrt") {
            if (x < 0) throw std::domain_error("Square root of negative number");
            return std::sqrt(x);
        }
        if (name == "cbrt") return std::cbrt(x);
        if (name == "abs") return std::abs(x);
        if (name == "floor") return std::floor(x);
        if (name == "ceil") return std::ceil(x);
        if (name == "round") return std::round(x);
        if (name == "exp") return std::exp(x);
        if (name == "ln") {
            if (x <= 0) throw std::domain_error("ln domain error (<=0)");
            return std::log(x);
        }
        if (name == "log" || name == "log10") {
            if (x <= 0) throw std::domain_error("log10 domain error (<=0)");
            return std::log10(x);
        }
        if (name == "log2") {
            if (x <= 0) throw std::domain_error("log2 domain error (<=0)");
            return std::log2(x);
        }

        // Trigonometric functions
        if (name == "sin") return std::sin(m_parent->toRadians(x));
        if (name == "cos") return std::cos(m_parent->toRadians(x));
        if (name == "tan") {
            double rad = m_parent->toRadians(x);
            if (std::abs(std::cos(rad)) < 1e-15) throw std::domain_error("tan undefined at asymptote");
            return std::tan(rad);
        }
        if (name == "sec") {
            double c = std::cos(m_parent->toRadians(x));
            if (std::abs(c) < 1e-15) throw std::domain_error("sec undefined at asymptote");
            return 1.0 / c;
        }
        if (name == "csc" || name == "cosec") {
            double s = std::sin(m_parent->toRadians(x));
            if (std::abs(s) < 1e-15) throw std::domain_error("cosec undefined at asymptote");
            return 1.0 / s;
        }
        if (name == "cot") {
            double t = std::tan(m_parent->toRadians(x));
            if (std::abs(t) < 1e-15) throw std::domain_error("cot undefined at asymptote");
            return 1.0 / t;
        }

        // Inverse Trigonometric functions
        if (name == "asin") {
            if (x < -1.0 || x > 1.0) throw std::domain_error("asin domain error [-1, 1]");
            return m_parent->fromRadians(std::asin(x));
        }
        if (name == "acos") {
            if (x < -1.0 || x > 1.0) throw std::domain_error("acos domain error [-1, 1]");
            return m_parent->fromRadians(std::acos(x));
        }
        if (name == "atan") return m_parent->fromRadians(std::atan(x));
        if (name == "asec" || name == "arcsec") {
            if (std::abs(x) < 1.0) throw std::domain_error("asec domain error (|x| >= 1)");
            return m_parent->fromRadians(std::acos(1.0 / x));
        }
        if (name == "acsc" || name == "acosec" || name == "arccsc") {
            if (std::abs(x) < 1.0) throw std::domain_error("acosec domain error (|x| >= 1)");
            return m_parent->fromRadians(std::asin(1.0 / x));
        }
        if (name == "acot" || name == "arccot") {
            if (x == 0.0) return m_parent->fromRadians(PI_VAL / 2.0);
            return m_parent->fromRadians(std::atan(1.0 / x));
        }
        if (name == "recip" || name == "inv") {
            if (x == 0.0) throw std::domain_error("Division by zero");
            return 1.0 / x;
        }

        // Hyperbolic functions
        if (name == "sinh") return std::sinh(x);
        if (name == "cosh") return std::cosh(x);
        if (name == "tanh") return std::tanh(x);
        if (name == "asinh") return std::asinh(x);
        if (name == "acosh") {
            if (x < 1.0) throw std::domain_error("acosh domain error (<1)");
            return std::acosh(x);
        }
        if (name == "atanh") {
            if (x <= -1.0 || x >= 1.0) throw std::domain_error("atanh domain error (-1, 1)");
            return std::atanh(x);
        }

        // 2-argument functions
        if (name == "pow") {
            if (args.size() < 2) throw std::runtime_error("pow requires 2 arguments");
            return std::pow(args[0], args[1]);
        }
        if (name == "ncr") {
            if (args.size() < 2) throw std::runtime_error("nCr requires 2 arguments");
            return combinations(args[0], args[1]);
        }
        if (name == "npr") {
            if (args.size() < 2) throw std::runtime_error("nPr requires 2 arguments");
            return permutations(args[0], args[1]);
        }

        throw std::runtime_error("Unknown function: " + name);
    }
};

