MathParser::MathParser(AngleUnit angleUnit) : m_angleUnit(angleUnit) {}

void MathParser::setAngleUnit(AngleUnit unit) {
    m_angleUnit = unit;
}

AngleUnit MathParser::angleUnit() const {
    return m_angleUnit;
}

double MathParser::toRadians(double angle) const {
    if (m_angleUnit == AngleUnit::Degrees) {
        return angle * (PI_VAL / 180.0);
    }
    return angle;
}

double MathParser::fromRadians(double radians) const {
    if (m_angleUnit == AngleUnit::Degrees) {
        return radians * (180.0 / PI_VAL);
    }
    return radians;
}

std::string MathParser::normalizeExpression(std::string_view expr) {
    std::string s(expr);

    // Replace display symbols with ascii
    auto replaceAll = [&](std::string_view from, std::string_view to) {
        size_t p = 0;
        while ((p = s.find(from, p)) != std::string::npos) {
            s.replace(p, from.length(), to);
            p += to.length();
        }
    };

    replaceAll("×", "*");
    replaceAll("÷", "/");
    replaceAll("−", "-");
    replaceAll("π", "pi");
    replaceAll("√", "sqrt");

    // Trim trailing whitespace
    while (!s.empty() && std::isspace(s.back())) s.pop_back();

    // Strip trailing binary operators if user pressed = without closing
    // e.g. "5 + 3 + " -> "5 + 3"
    while (!s.empty()) {
        char c = s.back();
        if (c == '+' || c == '*' || c == '/' || c == '^' || c == '%') {
            s.pop_back();
            while (!s.empty() && std::isspace(s.back())) s.pop_back();
        } else if (c == '-') {
            // Only strip minus if preceded by space or operator
            s.pop_back();
            while (!s.empty() && std::isspace(s.back())) s.pop_back();
        } else {
            break;
        }
    }

    // Auto-close open parentheses
    int openCount = 0;
    for (char c : s) {
        if (c == '(') openCount++;
        else if (c == ')') openCount--;
    }
    while (openCount > 0) {
        s += ')';
        openCount--;
    }

    return s;
}

std::string MathParser::handleOperatorInput(const std::string& currentText, const std::string& newOp) {
    std::string trimmed = currentText;
    while (!trimmed.empty() && std::isspace(trimmed.back())) trimmed.pop_back();

    if (trimmed.empty() || trimmed == "0") {
        if (newOp == "-") return "-";
        return "0 " + newOp + " ";
    }

    // Check if ends with a binary operator
    // Standard ops: +, -, *, /, ^, %
    char lastChar = trimmed.back();
    bool isLastOp = (lastChar == '+' || lastChar == '-' || lastChar == '*' || 
                     lastChar == '/' || lastChar == '^' || lastChar == '%');

    if (isLastOp) {
        // If last op is * or / or ^ and new op is -, treat as unary minus
        if ((lastChar == '*' || lastChar == '/' || lastChar == '^') && newOp == "-") {
            return currentText + "-";
        }

        // Check if there was already a unary minus, e.g. "* -"
        if (lastChar == '-' && trimmed.length() >= 2) {
            char prevChar = trimmed[trimmed.length() - 2];
            if (prevChar == ' ') {
                size_t p = trimmed.find_last_not_of(" \t", trimmed.length() - 2);
                if (p != std::string::npos && (trimmed[p] == '*' || trimmed[p] == '/' || trimmed[p] == '^')) {
                    // Replace the composite operator (e.g. "* -") with the new operator
                    std::string base = trimmed.substr(0, p);
                    while (!base.empty() && std::isspace(base.back())) base.pop_back();
                    return base + " " + newOp + " ";
                }
            }
        }

        // Replace the trailing operator
        trimmed.pop_back();
        while (!trimmed.empty() && std::isspace(trimmed.back())) trimmed.pop_back();
        return trimmed + " " + newOp + " ";
    }

    return currentText + " " + newOp + " ";
}

std::string MathParser::formatNumber(double value, int maxDecimals) {
    if (std::isnan(value)) return "NaN";
    if (std::isinf(value)) return (value > 0) ? "Infinity" : "-Infinity";

    // Clean up negative zero
    if (value == 0.0) return "0";

    // Check for large numbers or small numbers requiring scientific notation
    double absVal = std::abs(value);
    if ((absVal >= 1e15 || (absVal < 1e-6 && absVal > 0.0))) {
        std::ostringstream ss;
        ss << std::scientific << std::setprecision(8) << value;
        return ss.str();
    }

    // Standard decimal formatting
    std::ostringstream ss;
    ss << std::fixed << std::setprecision(maxDecimals) << value;
    std::string s = ss.str();

    // Strip trailing zeros after dot
    if (s.find('.') != std::string::npos) {
        while (!s.empty() && s.back() == '0') s.pop_back();
        if (!s.empty() && s.back() == '.') s.pop_back();
    }

    return s.empty() ? "0" : s;
}

EvalResult MathParser::evaluate(std::string_view expression) {
    EvalResult res;
    std::string normalized = normalizeExpression(expression);

    if (normalized.empty()) {
        res.success = true;
        res.value = 0.0;
        res.formatted = "0";
        return res;
    }

    try {
        RecursiveDescentParser parser(normalized, this);
        double val = parser.parse();

        // Round very close to zero values (e.g. sin(pi))
        if (std::abs(val) < 1e-15) val = 0.0;

        res.success = true;
        res.value = val;
        res.intValue = static_cast<int64_t>(val);
        res.formatted = formatNumber(val);
    } catch (const std::exception& e) {
        res.success = false;
        res.errorMessage = e.what();
    }

    return res;
}

